const { IncomingWebhook } = require('@slack/webhook');

/**
 * @param {string} text - The message content to post to Slack.
 * @param {string} channelId - The Slack channel ID (e.g., 'C1234567890abcdef') where the message should be posted.
 * @param {string} [webhookUrl='YOUR_SLACK_WEBHOOK_URL'] -  Your Slack webhook URL for posting messages. **Replace 'YOUR_SLACK_WEBHOOK_URL' with your actual URL.**
 * @returns {Promise<void>} Resolves upon successful message posting.
 */
async function postToSlack(text, channelId, webhookUrl = 'YOUR_SLACK_WEBHOOK_URL') {
  try {
    // Create a Slack webhook client using the provided URL
    const webhook = new IncomingWebhook(webhookUrl);

    // Construct the Slack message payload
    const payload = {
      channel: channelId, // Specify the target channel
      text: text,
    };

    // Send the message asynchronously via the webhook
    await webhook.send(payload);
    console.log(`Successfully posted message "${text}" to channel ${channelId}`); 
  } catch (error) {
    console.error(`Error posting to Slack:`, error);
    // Handle errors appropriately (e.g., logging, retries, notifications)
  }
}

// **Example Usage:**
postToSlack("This is an automated message from my JavaScript function!", 'C123ABC45DEF67890', 'https://hooks.slack.com/services/T00000000/B00000000/XXXXXXXXXXXXXXXXXXXX'); 
```

