```cpp
#include <iostream>
#include <limits>

using namespace std;

// Recursive Fibonacci function
int fibonacci(int a, int b, int n) {
    if (n == 1) return a;
    if (n == 2) return b;
    return fibonacci(b, a + b, n - 1);
}

// Function to generate and display the Fibonacci sequence
void generateFibonacci(int start1, int start2, int count) {
    // Input Validation: Ensure valid numeric inputs and non-negative counts
    if (!isdigit(to_string(start1).c_str()) || !isdigit(to_string(start2).c_str()) || count <= 0) {
        cerr << "Error: Invalid input. Please enter two numeric starting values and a positive count." << endl;
        return; // Exit gracefully if errors found
    }

    int num1 = stoi(to_string(start1));
    int num2 = stoi(to_string(start2));

    cout << num1 << ", " << num2 << ", ";  // Output initial values

    for (int i = 3; i <= count; ++i) {
        int nextFib = fibonacci(num1, num2, i);
        cout << nextFib << ", ";
        // Update for next iteration
        num1 = num2;
        num2 = nextFib;
    }
    cout << endl; 
}

int main() {
    int start1, start2, count;

    cout << "Enter the first two Fibonacci numbers: ";
    cin >> start1 >> start2;

    cout << "Enter the desired sequence length: ";
    cin >> count;

    generateFibonacci(start1, start2, count);

    return 0;
}
```

