func generateSportComparison(sportPreference: String) -> [[String]] {
    let factors = ["Speed", "Difficulty", "Style", "Learning Curve", "Terrain Variety", "Trick Opportunities"]
    var comparisonTable: [[String]] = [] //  2D array to mimic Excel structure

    // Header Row
    comparisonTable.append(["Factor".uppercased(), "Skiing", "Snowboarding"])

