            case "Speed": rowData[1] = "**High** (Greater top speeds achievable)"
            case "Terrain Variety": rowData[1] = "**Excellent** (Wide range adaptable)"
            case "Learning Curve": rowData[1] = "Moderate (Initial basics quicker, advanced techniques take time)"
            default: rowData[1] =  describeFactor(factor: factor, for: sportPreference) // Generic description
            }
            rowData[2] = describeFactor(factor: factor, for: "snowboarding") // Contrast for snowboarding
        case "snowboarding":
